mapper.select:
select p.DZZDM,p.DZZMC,p.ZZLB, count(c.DZZDM) as CHILDCOUNT,-- 下级组织个数 0 as CHILDSHOW,-- 是否显示下级组织 p.DZZDM NODECODE,-- 组织代码 SUBSTR(p.DZZDM,1,LENGTH(p.DZZDM)-3) PARENTCODE -- 父级组织代码 from ZZ_ZZQKXX p left join ZZ_ZZQKXXFB fb on p.DZZDM= fb.DZZDM left join ( select c.* from ZZ_ZZQKXX c left join ZZ_ZZQKXXFB cfb on c.DZZDM= cfb.DZZDM where 1=1
and cfb.ZZLB in(#{showlevel}) -- 党总支
) c on p.dzzdm=SUBSTR(c.DZZDM,1,LENGTH(c.DZZDM)-3) left join ZZ_DZZFBQK fbType on p.DZZDM = fbType.DZZDM where 1=1 and p.DZZDM like concat('',#{parentCode},'%') and length(p.DZZDM)=(length(#{parentCode})+3)
and p.DZZDM = #{dzzdm}
and fb.ZZLB in
#{level}
group by p.DZZDM,p.DZZMC,p.ZZLB,fbType.SORT -- order by PARENTCODE,NODECODE order by p.DZZDM

select p.ZZQKXXBS, p.DZZDM, p.DZZMC,fb.ZZLB, fb.JCZZFL, p.JLDZZRQ, p.SCYTDZB, p.KZPYRQ, p.JSPYRQ, p.YL01, p.YL02,
p.YL03, p.YL04, p.YL05,z.HZMC as ZZLBMC,j.HZMC as JCZZFLMC,
p.DZZDM NODECODE,SUBSTR(p.DZZDM,1,LENGTH(p.DZZDM)-3) PARENTCODE,
ifnull(fb.ZGRS,0) as ZGRS,fb.LDJTJC,bz.LDJTDXRQ as SCHJSJ,bz.GJJMRQ,
ifnull(fb.DYZS,0) as USERCOUNT
from ZZ_ZZQKXX p
left join ZZ_ZZQKXXFB fb on p.DZZDM=fb.DZZDM
left join zzzd_zzlbdmnew z on fb.ZZLB = z.BM
left join zzzd_jczzflnew j on fb.JCZZFL = j.BM
left join ZZ_BZJCXX bz on p.DZZDM = bz.DZZDM and bz.LDJTJC = fb.LDJTJC
left join ZZ_ZZQKXX dw on SUBSTR(p.DZZDM,1,12)=dw.DZZDM
left join VM_PARTYGROUP partyGroup on dw.DZZDM = partyGroup.DZZDM

    inner join (
       select * from (select zz.DZZDM,zz.DZZMC,
          (case when t.GJJMRQ is null then zz.JLDZZRQ else t.GJJMRQ end) as hjsj
          from ZZ_ZZQKXX zz
          left join (
              select distinct bz.DZZDM,bz.GJJMRQ from ZZ_ZZQKXXFB fb
              inner join ZZ_BZJCXX bz on fb.DZZDM = bz.DZZDM and fb.LDJTJC = bz.LDJTJC
              where bz.GJJMRQ is not null
          ) t on zz.DZZDM = t.DZZDM
          where zz.dzzdm like concat('',#{gddwdm},'%')
      ) t where 1=1

          and t.hjsj >= #{jmrq_begintime}


          and t.hjsj  <=  #{jmrq_endtime}

    ) t on p.DZZDM=t.DZZDM

where 1=1 and p.DZZDM like concat('',#{gddwdm},'%')

    and p.DZZDM like concat('',#{parentCode},'%')

        and (p.DZZDM = #{parentCode} or length(p.DZZDM)=(length(#{parentCode})+3))


        and length(p.DZZDM)=(length(#{parentCode})+3)



    and p.DZZMC like concat('%',#{dzzmc},'%')


    and p.DZZDM like concat('%',#{dzzdm},'%')


    and fb.ZZLB = #{zzlb}


    and fb.JCZZFL = #{jczzfl}


    and p.JLDZZRQ >= #{jldzzrq_begin}


    and p.JLDZZRQ  <=  #{jldzzrq_end}


    and SUBSTR(p.DZZDM,1,12) in(select DZZDM from ZZ_DZZFBQK where ZZFB= #{zzfbType})


    and fb.ZZLB in

        #{zzlb}



    and fb.JCZZFL in

        #{jczzfl}



    and p.DZZDM = #{ssdzzdm}



        and fb.ZZLB='100' and length(p.DZZDM)=12


        and fb.ZZLB='100' and length(p.DZZDM)=15



    and (
    substr(p.JLDZZRQ,1,4) = #{hjYear}

        or p.DZZDM in (
        select DZZDM from ZZ_BZJCXX
        where 1=1

            and GJJMRQ >= #{jmrq_begintime}


            and GJJMRQ  <=  #{jmrq_endtime}


            and DZZDM like concat('%',#{dzzdm},'%')

        )

    )


    and partyGroup.GROUPID like concat('%',#{partyGroupId},'%')


    and p.DZZDM not  in

        #{dzzdm}


order by PARENTCODE,NODECODE

select * from ( select 1 as "nodetype", z.JGFZID as "id", z.FJGFZID as "parentId", z.FZMC as "name", count(1) as "partyCount", z.orderby as "sort", 0 as "isexpand" from DJZZRS_JGFZ z left join DJZZRS_FZJGGL g on z.JGFZID = g.JGFZID left join DJZZRS_JGFZ c on z.JGFZID = c.FJGFZID where 1=1
and z.FJGFZID is null
and z.FJGFZID =#{parentId}
group by z.JGFZID,z.FJGFZID,z.FZMC,z.ORDERBY union select 2 as "nodetype", p.DZZDM as "id", z.JGFZID as "parentId", p.DZZMC as "name", count(c.DZZDM) as "partyCount",-- 下级组织个数 fbType.SORT as "sort", 0 as "isexpand" from DJZZRS_JGFZ z inner join DJZZRS_FZJGGL g on z.JGFZID = g.JGFZID inner join ZZ_ZZQKXX p on g.DZZBM = p.DZZDM and length(p.DZZDM) = 12 left join ZZ_DZZFBQK fbType on p.DZZDM = fbType.DZZDM left join ( select c.* from ZZ_ZZQKXX c left join ZZ_ZZQKXXFB cfb on c.DZZDM= cfb.DZZDM where 1=1
and cfb.ZZLB in('100','200') -- 党委
and cfb.ZZLB in('100','200') and LENGTH(c.DZZDM)=12 -- 一级党委
) c on p.DZZDM=SUBSTR(c.DZZDM,1,LENGTH(c.DZZDM)-3)
where 1=1
and z.JGFZID = #{parentId}
group by p.DZZDM,p.DZZMC,z.JGFZID,fbType.SORT ) t order by t.sort

select p.DZZDM,p.DZZMC, (select count(*) from ZZ_ZZQKXX c inner join ZZ_ZZQKXXFB fb on c.DZZDM=fb.DZZDM where p.DZZDM=SUBSTR(c.DZZDM,1,length(p.DZZDM)) and p.DZZDM!=c.DZZDM and fb.ZZLB !='500') as CHILDCOUNT from ZZ_ZZQKXX p where 1=1
and p.DZZDM like concat('',#{dzzdm},'%')
and p.DZZDM = #{ssdzzdm}

select ifnull(fb.DYZS,0) as USERCOUNT from ZZ_ZZQKXX p
inner join ZZ_ZZQKXXFB fb on p.DZZDM=fb.DZZDM
where 1=1 and p.DZZDM = #{dzzdm}

select z.DZZDM,z.DZZMC from ZZ_ZZQKXX z where 1=1
and z.DZZDM in
#{dzzdm}

select party.DZZDM as id,SUBSTR(party.DZZDM,1,LENGTH(party.DZZDM)-3) as parentid,party.DZZMC as name from ZZ_ZZQKXX party where 1=1 and party.DZZDM like concat('',#{gddwdm},'%')
and SUBSTR(party.DZZDM,1,LENGTH(party.DZZDM)-3)=#{parentId}
order by parentid,id
